

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% make_results.m
%
% This pipeline aggregates session-level neural data across recordings and
% performs population-level analyses comparing task conditions.
%
% -------------------------------------------------------------------------
% HOW TO RUN THIS FUNCTION:
%
%This script operates on precomputed session-level data structures
% generated by the preprocessing pipeline (build_all_data_structures).
%
% After preprocessing, data must be organized as:
%
%   Exp1/
%       └── M1/
%            └── All_Data_Structures/
%                      ├── session1.mat
%                      ├── session2.mat
%                      └── ...
%
%To run this analysis, pass the path to the corresponding
% "All_Data_Structures" directory as input:
%
% results = make_results('./Exp1/M1/All_Data_Structures', 'M1');
% -------------------------------------------------------------------------
% NOTE ON TASK NAMING:
% At the data-processing stage, task conditions were labeled as "main"
% and "control" for organizational and file-naming purposes.
%
% In the manuscript and analyses, these conditions correspond to:
%   control  → TD condition
%   main     → PC conditi
% -------------------------------------------------------------------------
%
% The pipeline:
%   1) Aggregates neural responses across sessions
%   2) Computes stimulus dissimilarity matrices
%   3) Performs statistical comparisons between tasks
%   4) Computes bootstrapped PSTHs (raw and normalized)
%   5) Exports neural response matrices for decoding analyses
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function results = make_results(folder_name, monkey_name)

    
    % Load and concatenate data across all sessions for the specified monkey
    results = collect_all_sessions(folder_name, monkey_name);
    
    %%%%%%%%%%%%%%%%%%%%% Stimulus dissimilarity analysis %%%%%%%%%%%%%%%%%

    % Compute population-level stimulus dissimilarity matrices based on
    % normalized neural response patterns and compare within-task structure

    [dissimilarity_matrix, dissimilarity_vector, stim_list_control_main] = compute_dissimilarity_matrix(results.all_stimuli_respons_main, results.all_stimuli_respons_control, results.stimlist);
    
    fig_diss = plot_dissimilarity_matrix(dissimilarity_matrix, dissimilarity_vector, stim_list_control_main);
    
    diss_blocks = extract_dissimilarity_blocks(dissimilarity_matrix);
    
    [p_s, h_s, stats_s] = signrank(diss_blocks.control_dist_vector, diss_blocks.main_dist_vector);
    fig_scatter = plot_dissimilarity_scatter(diss_blocks.control_dist_vector, diss_blocks.main_dist_vector, p_s);
    
     
    %%%%%%%%%%%%%%% Statistical comparison of neural responses %%%%%%%%%%%%  
    % Compare population responses between tasks for:
   
    % All stimuli  
    response_window = 350:549;
    [p, h, stats] = compare_response_windows(results.all_all_stimuli_data_control, results.all_all_stimuli_data_main, response_window);
    
    % Preferred (high-response) stimuli
    [p_h, h_h, stats_h] = compare_response_windows(results.all_high_stimuli_data_control, results.all_high_stimuli_data_main, response_window);
     
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%% Population PSTHs %%%%%%%%%%%%%%%%%%%
    
    % Compute bootstrapped PSTHs with confidence intervals
 
    numBootstrapSamples = 1000;
    bin_size = 10;
    
    % All stimuli 
    psth = compute_bootstrap_psth(results.all_all_stimuli_data_control, results.all_all_stimuli_data_main, numBootstrapSamples, bin_size);
    fig = plot_bootstrap_psth(psth, p);
    
    % Preferred (high-response) stimuli
    psth = compute_bootstrap_psth(results.all_high_stimuli_data_control, results.all_high_stimuli_data_main, numBootstrapSamples, bin_size);
    fig_h = plot_bootstrap_psth(psth, p_h);
    

    %%%%%%%%%%%%%%%%%%%%% Normalized PSTH analysis %%%%%%%%%%%%%%%%%%%%%%%

    % Normalize responses per unit to compare the time course of activity
    % between control and main conditions

    response_bins = 35:55;
    psth_norm_a = compute_bootstrap_psth_with_normalization(results.all_all_stimuli_data_control, results.all_all_stimuli_data_main, numBootstrapSamples, bin_size);
    [p_norm_a, h_norm_a, stats_norm_a] = compare_response_windows_normalized_binned(psth_norm_a.unit_binned_control_norm, psth_norm_a.unit_binned_main_norm, response_bins);  
    fig_norm_a = plot_normalized_bootstrap_psth (psth_norm_a , p_norm_a );

    psth_norm_h = compute_bootstrap_psth_with_normalization(results.all_high_stimuli_data_control, results.all_high_stimuli_data_main, numBootstrapSamples, bin_size);
    [p_norm_h, h_norm_h, stats_norm_h] = compare_response_windows_normalized_binned(psth_norm_h.unit_binned_control_norm, psth_norm_h.unit_binned_main_norm, response_bins);  
    fig_norm_h = plot_normalized_bootstrap_psth (psth_norm_h , p_norm_h );

    %%%%%%%%%%%%%%%%%%%%%%%%%% Save SVM decoding datasets %%%%%%%%%%%%%%%%%
    % Export medium-stimulus responses and binned neural data for decoding analyses

    all_response_firing_medium_main = results.all_response_firing_medium_main';
    all_response_firing_medium_control = results.all_response_firing_medium_control';
    
    out_folder = 'svm_data';

    if ~exist(out_folder, 'dir')
        mkdir(out_folder);
    end

    headers = results.all_channels_names';
    file_name = fullfile(out_folder, ...
        [char(results.monkey_name), '_all_response_firing_medium_TD.csv']);
    writecell([headers; num2cell(all_response_firing_medium_control)], file_name);
    
    headers = results.all_channels_names';
    file_name = fullfile(out_folder, ...
        [char(results.monkey_name), '_all_response_firing_medium_PC.csv']);
    writecell([headers; num2cell(all_response_firing_medium_main)], file_name);

end
 


% Load and aggregate session-level data structures across recordings,
% selecting units that are responsive and selective in either control
% or main conditions based on statistical, z-score and reliability criteria

function results = collect_all_sessions(folder_name, monkey_name)

    % -------------------- file list --------------------
    mat_files = dir(fullfile(folder_name, '*.mat'));
    loaded_structures = {};

    % -------------------- initialize variables --------------------
    all_channels = [];
    all_channels_names = [];
    all_mean_response_main = [];
    all_mean_response_control = [];
    all_reliability_control = [];
    all_reliability_main = [];
    channels_main = [];
    channels_control = [];
    interested_channels_control = [];
    interested_channels_main = [];
    all_stimuli_respons_control = [];
    all_stimuli_respons_main = [];
    all_high_stimuli_response_control = [];
    all_high_stimuli_response_main = [];
    all_high_stimuli_data_control = [];
    all_high_stimuli_data_main = [];
    all_all_stimuli_data_control = [];
    all_all_stimuli_data_main = [];
    all_response_firing_medium_control = [];
    all_response_firing_medium_main = [];
    %all_interested_channels = [];
    all_interested_channels = {};

    % -------------------- loop through files --------------------
    for i = 1:length(mat_files)
        file_path = fullfile(folder_name, mat_files(i).name);
        loaded_data = load(file_path);

        loaded_structures{i} = loaded_data;

        parts = strsplit(loaded_data.data_struct.data_name, '_');
        last_part = parts{end};
        interested_Task = last_part;

        disp(loaded_data.data_struct.data_name);

        all_channels = 1:length(loaded_data.data_struct.channel_names);

        %%%%%%%%%%%%%%%%%%%%%%%%% interested_channels %%%%%%%%%%%%%%%%%%%%%%%%%

        if interested_Task == "control"
            interested_channels_control = loaded_data.data_struct.channels_above_z4;

            mean_response_control = loaded_data.data_struct.mean_response_all_stimuli(all_channels);
            reliability_control = loaded_data.data_struct.reliability(all_channels);
            stimuli_respons_control = loaded_data.data_struct.mean_response;
            high_stimuli_response_control = loaded_data.data_struct.high_stimuli_response;
            data_high_stimuli_control = loaded_data.data_struct.data_high_stimuli;
            data_all_stimuli_control = loaded_data.data_struct.all_stimuli_response;
            response_firing_medium_control = loaded_data.data_struct.response_firing_medium_stimuli;
        end

        if interested_Task == "main"
            interested_channels_main = loaded_data.data_struct.channels_above_z4;

            mean_response_main = loaded_data.data_struct.mean_response_all_stimuli(all_channels);
            reliability_main = loaded_data.data_struct.reliability(all_channels);
            stimuli_respons_main = loaded_data.data_struct.mean_response;
            high_stimuli_response_main = loaded_data.data_struct.high_stimuli_response;
            data_high_stimuli_main = loaded_data.data_struct.data_high_stimuli;
            data_all_stimuli_main = loaded_data.data_struct.all_stimuli_response;
            response_firing_medium_main = loaded_data.data_struct.response_firing_medium_stimuli;

            if isfield(loaded_data.data_struct, 'stimlist')
                stimlist = loaded_data.data_struct.stimlist;
            else
                disp('stimlist does not exist.');
            end
        end

        if ~isempty(interested_channels_control) && ~isempty(interested_channels_main)
            interested_chann = union(interested_channels_main, interested_channels_control);

            channels_rel_control = find(reliability_control >= 0.5);
            channels_rel_main = find(reliability_main >= 0.5);
            interested_chann_main = intersect(interested_channels_main, channels_rel_main);
            interested_chann_control = intersect(interested_channels_control, channels_rel_control);
            interested_channels = union(interested_chann_main, interested_chann_control);
     
            %interested_channels = interested_chann ;
            % disp(interested_channels);

            all_channel_idx = [];

            for k = 1:length(interested_channels)
                channel_idx = find(all_channels == interested_channels(k));
                all_channel_idx = [all_channel_idx, channel_idx];
            end

            all_mean_response_main = [all_mean_response_main; mean_response_main(all_channel_idx)'];
            all_mean_response_control = [all_mean_response_control; mean_response_control(all_channel_idx)'];

            channel_names = cellstr(loaded_data.data_struct.channel_names);
            channels = channel_names(all_channel_idx);
            all_channels_names = [all_channels_names; channels];

            all_reliability_control = [all_reliability_control; reliability_control(all_channel_idx)'];
            all_reliability_main = [all_reliability_main; reliability_main(all_channel_idx)'];

            all_high_stimuli_response_control = [all_high_stimuli_response_control; high_stimuli_response_control(all_channel_idx)'];
            all_high_stimuli_response_main = [all_high_stimuli_response_main; high_stimuli_response_main(all_channel_idx)'];

            all_high_stimuli_data_control = [all_high_stimuli_data_control; data_high_stimuli_control(all_channel_idx, :)];
            all_high_stimuli_data_main = [all_high_stimuli_data_main; data_high_stimuli_main(all_channel_idx, :)];

            all_all_stimuli_data_control = [all_all_stimuli_data_control; data_all_stimuli_control(all_channel_idx, :)];
            all_all_stimuli_data_main = [all_all_stimuli_data_main; data_all_stimuli_main(all_channel_idx, :)];

            all_response_firing_medium_control = [all_response_firing_medium_control; response_firing_medium_control(:, all_channel_idx)'];
            all_response_firing_medium_main = [all_response_firing_medium_main; response_firing_medium_main(:, all_channel_idx)'];

            all_stimuli_respons_control = [all_stimuli_respons_control; stimuli_respons_control(:, all_channel_idx)'];
            all_stimuli_respons_main = [all_stimuli_respons_main; stimuli_respons_main(:, all_channel_idx)'];

            %all_interested_channels = [all_interested_channels; interested_channels(:)'];
            all_interested_channels{end+1,1} = interested_channels(:)';

            mean_response_control = [];
            mean_response_main = [];
            interested_channels_control = [];
            interested_channels_main = [];
            all_channels = [];
            interested_channels = [];
            data_high_stimuli_control = [];
            data_high_stimuli_main = [];
            data_all_stimuli_control = [];
            data_all_stimuli_main = [];
        end
    end

    % -------------------- save outputs in struct --------------------
    results.folder_name = folder_name;
    results.monkey_name = monkey_name;
    results.loaded_structures = loaded_structures;

    results.all_channels = all_channels;
    results.all_channels_names = all_channels_names;
    results.all_mean_response_main = all_mean_response_main;
    results.all_mean_response_control = all_mean_response_control;
    results.all_reliability_control = all_reliability_control;
    results.all_reliability_main = all_reliability_main;
    results.channels_main = channels_main;
    results.channels_control = channels_control;
    results.all_stimuli_respons_control = all_stimuli_respons_control;
    results.all_stimuli_respons_main = all_stimuli_respons_main;
    results.all_high_stimuli_response_control = all_high_stimuli_response_control;
    results.all_high_stimuli_response_main = all_high_stimuli_response_main;
    results.all_high_stimuli_data_control = all_high_stimuli_data_control;
    results.all_high_stimuli_data_main = all_high_stimuli_data_main;
    results.all_all_stimuli_data_control = all_all_stimuli_data_control;
    results.all_all_stimuli_data_main = all_all_stimuli_data_main;
    results.all_response_firing_medium_control = all_response_firing_medium_control;
    results.all_response_firing_medium_main = all_response_firing_medium_main;
    results.all_interested_channels = all_interested_channels;

    if exist('stimlist', 'var')
        results.stimlist = stimlist;
    else
        results.stimlist = [];
    end
end

% %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%% Functions %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

 
% Generate bootstrap resamples of data by randomly sampling units
% (rows) with replacement

 function [bootSamples] = bootstrap_rows(data, numBootstrapSamples)
     [numRows, numCols] = size(data);
     
     bootSamples = zeros(numBootstrapSamples, numRows, numCols);
     
     for i = 1:numBootstrapSamples
         % Randomly sample row indices with replacement
         sampledIndices = randi(numRows, numRows, 1);  % Resample row indices
         bootSamples(i, :, :) = data(sampledIndices, :);  % Store the bootstrapped sample
     end
 end


 % Compute a stimulus dissimilarity matrix based on correlation distance (1 - correlation)
 % between normalized population response vectors for control and main tasks

 function [dissimilarity_matrix, dissimilarity_vector, stim_list_control_main] = compute_dissimilarity_matrix(all_stimuli_respons_main, all_stimuli_respons_control, stimlist)

    all_control_main_stimuli_responses = [all_stimuli_respons_main, all_stimuli_respons_control];

    row_max = max(all_control_main_stimuli_responses, [], 2);
    normalized_matrix = all_control_main_stimuli_responses ./ row_max;

    transposed_responses = normalized_matrix';
    dissimilarity_vector = pdist(transposed_responses, 'correlation');
    dissimilarity_matrix = squareform(dissimilarity_vector);

    stim_list_control_main = [stimlist, stimlist];
 end


function fig = plot_dissimilarity_matrix(dissimilarity_matrix, dissimilarity_vector, stim_list_control_main)

    fig = figure('Color','w');
    ax = axes(fig);

    imagesc(ax, dissimilarity_matrix);
    axis(ax, 'image');
    axis(ax, 'tight');
    set(ax, 'YDir', 'reverse');
    colormap(ax, parula);

    max_l = max(dissimilarity_vector);
    caxis(ax, [0 max_l]);

    labels = string(stim_list_control_main);
    short_labels = extractBefore(labels, "_");

    G = 15;
    n = numel(short_labels);

    centers = abs(G/2) : G : (n - G/2 + 2);
    group_labels = short_labels(1:G:n);

    ax.XTick = centers;
    ax.YTick = centers;
    ax.XTickLabel = group_labels;
    ax.YTickLabel = group_labels;
    xtickangle(ax, 50);

    hold(ax, 'on');
    group = 120;
    bounds = group + 0.5 : G : group + 0.5;
    for b = bounds
        xline(ax, b, '-', 'Color', [0 0 0 0.25], 'LineWidth', 0.8, 'HandleVisibility', 'off');
        yline(ax, b, '-', 'Color', [0 0 0 0.25], 'LineWidth', 0.8, 'HandleVisibility', 'off');
    end
    hold(ax, 'off');

    set(ax, ...
        'FontName', 'Arial', ...
        'FontSize', 14, ...
        'LineWidth', 1.0, ...
        'TickDir', 'out', ...
        'Box', 'off', ...
        'TickLength', [0.012 0.012]);

    xlabel(ax, 'Stimuli', 'FontSize', 16, 'FontWeight', 'bold');
    ylabel(ax, 'Stimuli', 'FontSize', 16, 'FontWeight', 'bold');

    cb = colorbar;
    cb.Box = 'off';
    cb.Ticks = [0 max_l];
    cb.TickLabels = {'0', sprintf('%.1f', max_l)};
    cb.TickDirection = 'in';
    cb.FontName = 'Arial';
    cb.FontSize = 16;

    text(cb.Position(1) + cb.Position(1)/2, ...
         cb.Position(2) + cb.Position(2)/2, ...
         'Dissimilarity (1-Correlation)', ...
         'Units', 'normalized', ...
         'Rotation', 90, ...
         'HorizontalAlignment', 'center', ...
         'VerticalAlignment', 'middle', ...
         'FontName', 'Arial', ...
         'FontSize', 16);

    set(ax, 'Layer', 'top');
    set(findobj(ax, 'Type', 'image'), 'Interpolation', 'nearest');

    fig.Units = 'centimeters';
    fig.Position = [2 2 16 14];
    set(fig, 'Renderer', 'painters');
end

% Extract within-task and between-task dissimilarity blocks and convert
% them into vectorized forms for statistical analysis
function blocks = extract_dissimilarity_blocks(dissimilarity_matrix)

    N = size(dissimilarity_matrix, 1) / 2;

    if mod(N, 1) ~= 0
        error('Matrix size is not divisible by 2 — check input size!');
    end

    main_within = dissimilarity_matrix(1:N, 1:N);
    control_within = dissimilarity_matrix(N+1:end, N+1:end);
    between = dissimilarity_matrix(1:N, N+1:end);

    blocks.main_within = main_within;
    blocks.control_within = control_within;
    blocks.between = between;

    blocks.main_dist_vector = squareform(main_within);
    blocks.control_dist_vector = squareform(control_within);
    blocks.between_dist_vector = between(:);

    blocks.between_diag = diag(between);

    n = size(between, 1);
    between_vector = [];

    for i = 1:n-1
        between_vector = [between_vector, between(i, i+1:n)];
    end

    blocks.between_vector = between_vector(:);
end

% Compare summed neural responses across tasks within a specified
% response window using signrank test 
function [p, h, stats] =  compare_response_windows(stimuli_data_control, stimuli_data_main, response_window)

    all_stimuli_response_windows_control = stimuli_data_control(:, response_window);
    all_stimuli_response_windows_main = stimuli_data_main(:, response_window);

    all_stimuli_sum_response_control = sum(all_stimuli_response_windows_control, 2);
    all_stimuli_sum_response_main = sum(all_stimuli_response_windows_main, 2);

    [p, h, stats] = signrank(all_stimuli_sum_response_control, all_stimuli_sum_response_main);
end

% Compare summed binned neural responses across tasks using signrank test 
function [p, h, stats] = compare_response_windows_normalized_binned( binned_data_control_norm, binned_data_main_norm, response_bins)


    all_stimuli_response_windows_control = binned_data_control_norm(:, response_bins);
    all_stimuli_response_windows_main    = binned_data_main_norm(:, response_bins);

    all_stimuli_sum_response_control = sum(all_stimuli_response_windows_control, 2);
    all_stimuli_sum_response_main    = sum(all_stimuli_response_windows_main, 2);

    [p, h, stats] = signrank( ...
        all_stimuli_sum_response_control, ...
        all_stimuli_sum_response_main);
end
 
% Compute bootstrapped population PSTHs and confidence intervals by
% resampling units and temporally binning spike responses
function psth = compute_bootstrap_psth(all_all_stimuli_data_control, all_all_stimuli_data_main, numBootstrapSamples, bin_size)

    mean_condition_control = mean(all_all_stimuli_data_control, 1);
    mean_condition_main = mean(all_all_stimuli_data_main, 1);

    bootedData_control = bootstrap_rows(all_all_stimuli_data_control, numBootstrapSamples);
    bootedData_main = bootstrap_rows(all_all_stimuli_data_main, numBootstrapSamples);

    bootedData_control_mean = zeros(numBootstrapSamples, size(all_all_stimuli_data_control, 2));
    bootedData_main_mean = zeros(numBootstrapSamples, size(all_all_stimuli_data_main, 2));

    for k = 1:numBootstrapSamples
        bootedData_control_mean(k, :) = mean(squeeze(bootedData_control(k, :, :)), 1);
        bootedData_main_mean(k, :) = mean(squeeze(bootedData_main(k, :, :)), 1);
    end

    ci_control = prctile(bootedData_control_mean, [2.5, 97.5], 1);
    ci_main = prctile(bootedData_main_mean, [2.5, 97.5], 1);

    num_bins = floor(size(mean_condition_control, 2) / bin_size);

    binned_data_control = zeros(1, num_bins);
    binned_data_main = zeros(1, num_bins);
    binned_ci_control_lower = zeros(1, num_bins);
    binned_ci_control_upper = zeros(1, num_bins);
    binned_ci_main_lower = zeros(1, num_bins);
    binned_ci_main_upper = zeros(1, num_bins);

    for bin = 1:num_bins
        bin_start = (bin - 1) * bin_size + 1;
        bin_end = bin_start + bin_size - 1;

        binned_data_control(bin) = sum(mean_condition_control(bin_start:bin_end));
        binned_data_main(bin) = sum(mean_condition_main(bin_start:bin_end));

        binned_ci_control_lower(bin) = sum(ci_control(1, bin_start:bin_end));
        binned_ci_control_upper(bin) = sum(ci_control(2, bin_start:bin_end));
        binned_ci_main_lower(bin) = sum(ci_main(1, bin_start:bin_end));
        binned_ci_main_upper(bin) = sum(ci_main(2, bin_start:bin_end));
    end

    psth.binned_data_control = binned_data_control;
    psth.binned_data_main = binned_data_main;
    psth.binned_ci_control_lower = binned_ci_control_lower;
    psth.binned_ci_control_upper = binned_ci_control_upper;
    psth.binned_ci_main_lower = binned_ci_main_lower;
    psth.binned_ci_main_upper = binned_ci_main_upper;
    psth.num_bins = num_bins;
    psth.n_units = size(all_all_stimuli_data_control, 1);
end


% Compute normalized bootstrapped population PSTHs and confidence intervals by
% temporally binning unit responses, normalizing each unit by its maximum
% response across conditions, and resampling units
function psth = compute_bootstrap_psth_with_normalization( all_all_stimuli_data_control, all_all_stimuli_data_main, numBootstrapSamples, bin_size)

   
    assert(isequal(size(all_all_stimuli_data_control), size(all_all_stimuli_data_main)), ...
        'Control and main data must have the same size');

    time_window = 1:700;

    n_units = size(all_all_stimuli_data_control, 1);
    num_bins = floor(length(time_window) / bin_size);

    % ---------------------------------------------------------
    % 1) Bin each unit separately
    % Result: units x bins
    % ---------------------------------------------------------
    binned_control = bin_units( ...
        all_all_stimuli_data_control(:, time_window), ...
        bin_size);

    binned_main = bin_units( ...
        all_all_stimuli_data_main(:, time_window), ...
        bin_size);

    disp('binned_control_shape:');
    disp(size(binned_control));

    disp('binned_main_shape:');
    disp(size(binned_main));

    % ---------------------------------------------------------
    % 2) Find normalization value for each unit separately
    %
    % For each unit:
    %   max_control = max bin of control
    %   max_main    = max bin of main
    %
    % Then:
    %   norm_value = max(max_control, max_main)
    % ---------------------------------------------------------
    norm_value_per_unit = max([ ...
        max(binned_control, [], 2), ...
        max(binned_main, [], 2) ...
    ], [], 2);

    % Avoid division by zero or NaN
    norm_value_per_unit(norm_value_per_unit == 0 | isnan(norm_value_per_unit)) = 1;

    % ---------------------------------------------------------
    % 3) Normalize both binned matrices using the same value
    % for each unit
    % ---------------------------------------------------------
    binned_control_norm = binned_control ./ norm_value_per_unit;
    binned_main_norm    = binned_main    ./ norm_value_per_unit;

    % ---------------------------------------------------------
    % 4) Compute population mean after normalization
    % ---------------------------------------------------------
    psth.binned_data_control = mean(binned_control_norm, 1);
    psth.binned_data_main    = mean(binned_main_norm, 1);

    % ---------------------------------------------------------
    % 5) Bootstrap CI on normalized binned unit-level data
    % ---------------------------------------------------------
    ci_control = bootstrap_ci_units(binned_control_norm, numBootstrapSamples);
    ci_main    = bootstrap_ci_units(binned_main_norm, numBootstrapSamples);

    psth.binned_ci_control_lower = ci_control(1, :);
    psth.binned_ci_control_upper = ci_control(2, :);

    psth.binned_ci_main_lower = ci_main(1, :);
    psth.binned_ci_main_upper = ci_main(2, :);

    % ---------------------------------------------------------
    % 6) Save useful information
    % ---------------------------------------------------------
    psth.num_bins = num_bins;
    psth.n_units = n_units;

    psth.has_empty = false;

    psth.unit_binned_control_norm = binned_control_norm;
    psth.unit_binned_main_norm    = binned_main_norm;

    % Save normalization values
    psth.normalization_value_per_unit = norm_value_per_unit;
end

function binned_data = bin_units(data, bin_size)

    n_units = size(data, 1);
    num_bins = floor(size(data, 2) / bin_size);

    data = data(:, 1:num_bins * bin_size);

    data_reshaped = reshape(data, n_units, bin_size, num_bins);

    binned_data = reshape(sum(data_reshaped, 2), n_units, num_bins);
end


function ci = bootstrap_ci_units(unit_binned_data, numBootstrapSamples)

    n_units = size(unit_binned_data, 1);
    num_bins = size(unit_binned_data, 2);

    boot_means = zeros(numBootstrapSamples, num_bins);

    for k = 1:numBootstrapSamples
        sampled_units = randi(n_units, [n_units, 1]);
        boot_means(k, :) = mean(unit_binned_data(sampled_units, :), 1);
    end

    ci = prctile(boot_means, [2.5, 97.5], 1);
end


function fig = plot_bootstrap_psth(psth, p)

    control_dark = [0.00 0.30 0.60];
    main_dark    = [0.80 0.40 0.00];

    fig = figure('Color', 'w');
    hold on
    ax = gca;

    x = 1:psth.num_bins;

    fill([x fliplr(x)], ...
         [psth.binned_ci_control_upper * 100 fliplr(psth.binned_ci_control_lower * 100)], ...
         control_dark, 'FaceAlpha', 0.2, 'EdgeColor', 'none', 'HandleVisibility', 'off');

    fill([x fliplr(x)], ...
         [psth.binned_ci_main_upper * 100 fliplr(psth.binned_ci_main_lower * 100)], ...
         main_dark, 'FaceAlpha', 0.2, 'EdgeColor', 'none', 'HandleVisibility', 'off');

    plot(x, psth.binned_data_control * 100, 'LineWidth', 2.2, 'Color', control_dark, 'DisplayName', 'TD');
    plot(x, psth.binned_data_main * 100, 'LineWidth', 2.2, 'Color', main_dark, 'DisplayName', 'PC');

    maxi = max([psth.binned_data_main, psth.binned_data_control]) * 100 + 20;

    h1 = xline(30, '-', 'LineWidth', 1, 'Color', 'black');
    h2 = xline(60, '-', 'LineWidth', 1, 'Color', 'black');
    h1.HandleVisibility = 'off';
    h2.HandleVisibility = 'off';

    text(ax, 0.02, 0.98, sprintf('n = %d', psth.n_units), ...
        'Units', 'normalized', 'FontSize', 20, 'FontName', 'Arial', ...
        'VerticalAlignment', 'top', 'HorizontalAlignment', 'left');
    
    if p <0.05 color='red'; 
    else color = 'black';
    end

    text(ax, 0.02, 0.90, sprintf('p = %.2e', p), ...
        'Units', 'normalized', 'FontSize', 18, 'FontName', 'Arial', ...
        'Color', color , 'VerticalAlignment', 'top', 'HorizontalAlignment', 'left');

    xlabel('Time (ms)');
    ylabel('Firing rate (spikes/s)');

    set(ax, ...
        'FontName', 'Arial', ...
        'FontSize', 20, ...
        'LineWidth', 1.0, ...
        'TickDir', 'out', ...
        'Box', 'off', ...
        'XLim', [0 70], ...
        'XTick', [30 60], ...
        'XTickLabel', {'0', '300'}, ...
        'YLim', [0 maxi]);

    %legend('Location', 'northeastoutside', 'Box', 'off');
    hold off
end


